WITH filtered_customers AS (SELECT *, credit_limit * age AS credit_limit_times_age FROM customers WHERE email LIKE '%@startup.io' AND segment NOT IN ('SMB', 'Consumer')), customers_stats AS (SELECT is_active, SUM(credit_limit_times_age) AS total_credit_limit_times_age FROM filtered_customers GROUP BY is_active) SELECT * FROM customers_stats WHERE total_credit_limit_times_age < 240 ORDER BY total_credit_limit_times_age DESC
